        cli, "com.unauthorized.ForbiddenName", false
    );
    bool name_denied = (st_name != AISOC_DBUS_OK);
    TEST_CHECK(name_denied, "Policy denies unauthorized name acquisition (com.unauthorized.*)");

    /* 2. Call method on unauthorized destination outside whitelist */
    aisoc_dbus_method_call_t bad_call = {
        "com.unauthorized.Service", "/unauth", "com.unauthorized.Iface", "DoSomething"
    };
    aisoc_dbus_msg_t bad_req;
    aisoc_dbus_msg_init_call(&bad_call, &bad_req);
    aisoc_dbus_call_opts_t opts = { 200, false };
    aisoc_dbus_msg_t reply;
    aisoc_dbus_status_t st_call = aisoc_dbus_call_method(cli, &bad_req, &opts, &reply);
    aisoc_dbus_msg_unref(&bad_req);
    bool call_denied = (st_call != AISOC_DBUS_OK);
    if (st_call == AISOC_DBUS_OK) {
        aisoc_dbus_msg_unref(&reply);
    }
    TEST_CHECK(call_denied, "Policy denies method invocation to unauthorized destination");

    return name_denied && call_denied;
}

