static bool resolve_path(const char* rel_path, char* out_buf, size_t buf_len) {
    (void)buf_len;
    if (access(rel_path, F_OK) == 0) {
        if (realpath(rel_path, out_buf) != nullptr) {
            return true;
        }
    }
    const char* prefixes[] = {
        "../",
        "../../",
        "../../../",
        "../../../../",
        "../../../../../"
    };
    for (size_t i = 0; i < 5; ++i) {
        char tmp[512];
        snprintf(tmp, sizeof(tmp), "%s%s", prefixes[i], rel_path);
        if (access(tmp, F_OK) == 0) {
            if (realpath(tmp, out_buf) != nullptr) {
                return true;
            }
        }
    }
    return false;
}

