                  resolve_path("/usr/local/bin/dbus-daemon", daemon_bin, sizeof(daemon_bin)) ||
                  resolve_path("/usr/bin/dbus-daemon", daemon_bin, sizeof(daemon_bin));
    bool ok_lib = resolve_path("soc-ap/third_party/install/lib", lib_dir, sizeof(lib_dir)) ||
                  resolve_path("/usr/local/lib", lib_dir, sizeof(lib_dir));

    if (!ok_conf || !ok_bin) {
        return -1;
    }

    int pipefd[2];
    if (pipe(pipefd) != 0) {
        return -1;
    }
    pid_t pid = fork();
    if (pid == 0) {
        if (ok_lib) {
            setenv("LD_LIBRARY_PATH", lib_dir, 1);
        }
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[1]);
        execl(daemon_bin, daemon_bin, "--config-file", conf_path, "--print-address", nullptr);
        _exit(127);
    }
    close(pipefd[1]);
    ssize_t n = read(pipefd[0], out_addr, addr_len - 1);
    close(pipefd[0]);
    if (n <= 0) {
        kill(pid, SIGTERM);
        waitpid(pid, nullptr, 0);
        return -1;
    }
    out_addr[n] = '\0';
    char* nl = strchr(out_addr, '\n');
    if (nl != nullptr) {
        *nl = '\0';
    }
    return pid;
}

